      var fs = H("fieldset", { class: "lx-rb-comp" }, box), name = LX.uid("rb");
      var lg = H("legend", null, fs); H("b", { text: C.label }, lg);
      if (C.look) H("p", { class: "lx-rb-look", html: "<b>Look for:</b> " + LX.rich(C.look) }, fs);
      var row = H("div", { class: "lx-rb-levels" }, fs);
